INSERT INTO public.titles (id,type,title,genre,payload) VALUES
('f1','film','Orbit Terakhir','Sci-Fi','{"id":"f1","type":"film","title":"Orbit Terakhir","tagline":"Sejauh apa kamu akan mencari rumah?","genre":"Sci-Fi","year":2026,"rating":"8.7","age":"13+","duration":"1j 58m","image":"https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?auto=format&fit=crop&w=900&q=80","color":"#213855","cast":"Nara Putri, Arya Pradana, Bima Santosa","director":"Aditya Pramana","synopsis":"Sebuah sinyal misterius membawa astronaut muda ke stasiun luar angkasa yang telah lama ditinggalkan. Di antara kenangan dan batas waktu oksigen, ia harus memilih: pulang ke Bumi atau menemukan jawaban yang mengubah segalanya."}'::jsonb),
('f2','film','Setelah Hujan','Drama','{"id":"f2","type":"film","title":"Setelah Hujan","tagline":"Ada cerita yang belum selesai.","genre":"Drama","year":2026,"rating":"8.3","age":"13+","duration":"1j 42m","image":"https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=80","color":"#34214b","cast":"Laras Anindya, Dimas Raditya","director":"Kirana Dewi","synopsis":"Di kota yang selalu diguyur hujan, seorang fotografer menemukan surat-surat lama di toko buku kecil. Setiap surat membawanya lebih dekat kepada seseorang yang pernah ia lupakan."}'::jsonb),
('f3','film','Jalur Sunyi','Thriller','{"id":"f3","type":"film","title":"Jalur Sunyi","tagline":"Tidak semua jalan membawa pulang.","genre":"Thriller","year":2025,"rating":"8.1","age":"16+","duration":"1j 36m","image":"https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=900&q=80","color":"#173b32","cast":"Fajar Mahendra, Sinta Ayu","director":"Raka Wibawa","synopsis":"Perjalanan akhir pekan berubah menjadi teka-teki ketika tiga sahabat menemukan jalan yang tidak ada di peta. Mereka harus mengungkap rahasia hutan sebelum malam menutup semua arah."}'::jsonb),
('f4','film','Biru Tanpa Batas','Petualangan','{"id":"f4","type":"film","title":"Biru Tanpa Batas","tagline":"Petualangan dimulai dari keberanian.","genre":"Petualangan","year":2025,"rating":"8.5","age":"SU","duration":"1j 49m","image":"https://images.unsplash.com/photo-1518837695005-2083093ee35b?auto=format&fit=crop&w=900&q=80","color":"#15475a","cast":"Rani Puspita, Kevin Wijaya","director":"Dewangga Putra","synopsis":"Dua saudara berlayar mengikuti jurnal ayah mereka. Di pulau-pulau yang belum pernah mereka datangi, mereka menemukan arti keluarga dan keberanian untuk memulai kembali."}'::jsonb),
('f5','film','Kota Pukul Tiga','Drama','{"id":"f5","type":"film","title":"Kota Pukul Tiga","tagline":"Satu malam. Seribu kemungkinan.","genre":"Drama","year":2026,"rating":"7.9","age":"16+","duration":"1j 31m","image":"https://images.unsplash.com/photo-1519501025264-65ba15a82390?auto=format&fit=crop&w=900&q=80","color":"#49283b","cast":"Arga Wiratama, Nina Amalia","director":"Satria Wisesa","synopsis":"Seorang pengemudi malam dan penumpang terakhirnya melintasi kota yang hampir tertidur. Percakapan sederhana mengubah arah hidup keduanya sebelum matahari terbit."}'::jsonb),
('f6','film','Puncak Pertama','Petualangan','{"id":"f6","type":"film","title":"Puncak Pertama","tagline":"Langkah kecil, mimpi yang besar.","genre":"Petualangan","year":2024,"rating":"8.0","age":"SU","duration":"1j 45m","image":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=900&q=80","color":"#3d444a","cast":"Tara Kusuma, Bagas Aji","director":"Intan Maharani","synopsis":"Mahasiswa yang takut ketinggian bergabung dalam pendakian pertamanya. Persahabatan yang tumbuh di perjalanan membantunya menghadapi sesuatu yang lebih besar daripada gunung."}'::jsonb),
('s1','serial','Frekuensi 03','Sci-Fi','{"id":"s1","type":"serial","title":"Frekuensi 03","tagline":"Masa depan sedang menghubungi.","genre":"Sci-Fi","year":2026,"rating":"8.9","age":"13+","duration":"1 musim · 6 episode","episodes":6,"image":"https://images.unsplash.com/photo-1462331940025-496dfbfc7564?auto=format&fit=crop&w=900&q=80","color":"#49315b","cast":"Alif Ramadhan, Maya Sekar","director":"Rizky Darmawan","synopsis":"Sekelompok mahasiswa teknik menangkap siaran radio yang memprediksi kejadian esok hari. Setiap usaha mengubah masa depan justru membuka misteri yang lebih besar."}'::jsonb),
('s2','serial','Ruang 204','Drama','{"id":"s2","type":"serial","title":"Ruang 204","tagline":"Tetangga baru, cerita baru.","genre":"Drama","year":2026,"rating":"8.2","age":"13+","duration":"1 musim · 8 episode","episodes":8,"image":"https://images.unsplash.com/photo-1484154218962-a197022b5858?auto=format&fit=crop&w=900&q=80","color":"#615145","cast":"Nadia Safira, Galang Pratama","director":"Ayu Lestari","synopsis":"Lima penghuni kos dengan mimpi berbeda belajar hidup berdampingan. Dari tagihan listrik sampai tugas akhir, selalu ada cerita di balik pintu ruang 204."}'::jsonb),
('s3','serial','Arsip Tengah Malam','Thriller','{"id":"s3","type":"serial","title":"Arsip Tengah Malam","tagline":"Setiap berkas menyimpan rahasia.","genre":"Thriller","year":2025,"rating":"8.6","age":"16+","duration":"1 musim · 6 episode","episodes":6,"image":"https://images.unsplash.com/photo-1507842217343-583bb7270b66?auto=format&fit=crop&w=900&q=80","color":"#514030","cast":"Dian Paramita, Reza Anggara","director":"Damar Seno","synopsis":"Petugas arsip baru menemukan berkas orang hilang yang terus bertambah setiap tengah malam. Penyelidikannya membawa ia ke peristiwa yang sengaja dilupakan kota."}'::jsonb),
('f7','film','Sinyal dari Europa','Sci-Fi','{"id":"f7","type":"film","title":"Sinyal dari Europa","tagline":"Jawaban itu datang dari bawah es.","genre":"Sci-Fi","year":2026,"rating":"8.4","age":"13+","duration":"1j 54m","image":"https://images.unsplash.com/photo-1462331940025-496dfbfc7564?auto=format&fit=crop&w=900&q=80","color":"#29365b","cast":"Maya Sekar, Bima Santosa","director":"Rizky Darmawan","synopsis":"Tim peneliti menerima pola suara dari samudra di bawah permukaan Europa. Ketika komunikasi dengan Bumi terputus, seorang ahli bahasa harus menentukan apakah sinyal itu merupakan peringatan atau undangan."}'::jsonb),
('f8','film','Mesin Kenangan','Sci-Fi','{"id":"f8","type":"film","title":"Mesin Kenangan","tagline":"Tidak semua kenangan ingin ditemukan.","genre":"Sci-Fi","year":2025,"rating":"8.2","age":"13+","duration":"1j 47m","image":"https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=80","color":"#46315a","cast":"Alif Ramadhan, Laras Anindya","director":"Aditya Pramana","synopsis":"Seorang teknisi memperbaiki alat yang dapat memutar kembali ingatan manusia. Ia menemukan kenangan tentang sebuah keluarga yang tidak pernah tercatat dalam hidupnya dan mulai mempertanyakan asal ingatannya sendiri."}'::jsonb),
('f9','film','Langit Kedua','Sci-Fi','{"id":"f9","type":"film","title":"Langit Kedua","tagline":"Rumah bukan sekadar tempat berpijak.","genre":"Sci-Fi","year":2024,"rating":"7.8","age":"SU","duration":"1j 38m","image":"https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?auto=format&fit=crop&w=900&q=80","color":"#24465c","cast":"Nara Putri, Kevin Wijaya","director":"Dewangga Putra","synopsis":"Di koloni pertama di luar Bumi, seorang anak menanam benih terakhir milik neneknya. Usaha kecil itu mempertemukan warga yang telah lama kehilangan harapan untuk membangun rumah baru bersama."}'::jsonb),
('f10','film','Kedai Sebelum Pagi','Drama','{"id":"f10","type":"film","title":"Kedai Sebelum Pagi","tagline":"Setiap meja punya cerita.","genre":"Drama","year":2026,"rating":"8.1","age":"SU","duration":"1j 35m","image":"https://images.unsplash.com/photo-1442512595331-e89e73853f31?auto=format&fit=crop&w=900&q=80","color":"#574034","cast":"Nina Amalia, Galang Pratama","director":"Ayu Lestari","synopsis":"Pemilik kedai kopi dekat terminal memutuskan membuka usahanya untuk satu malam terakhir. Para pelanggan yang datang membantunya menyadari bahwa tempat sederhana itu telah menjadi rumah bagi banyak orang."}'::jsonb),
('f11','film','Surat untuk Timur','Drama','{"id":"f11","type":"film","title":"Surat untuk Timur","tagline":"Ada rindu yang menunggu alamat.","genre":"Drama","year":2025,"rating":"8.5","age":"13+","duration":"1j 51m","image":"https://images.unsplash.com/photo-1507842217343-583bb7270b66?auto=format&fit=crop&w=900&q=80","color":"#514432","cast":"Dian Paramita, Arga Wiratama","director":"Kirana Dewi","synopsis":"Seorang pustakawan menemukan surat yang tidak pernah dikirim di dalam buku sumbangan. Pencarian penerimanya membawa ia bertemu keluarga yang terpisah oleh keputusan masa lalu."}'::jsonb),
('f12','film','Nada yang Tertinggal','Drama','{"id":"f12","type":"film","title":"Nada yang Tertinggal","tagline":"Pulang kadang dimulai dari sebuah lagu.","genre":"Drama","year":2024,"rating":"7.9","age":"13+","duration":"1j 44m","image":"https://images.unsplash.com/photo-1511379938547-c1f69419868d?auto=format&fit=crop&w=900&q=80","color":"#4a3047","cast":"Nadia Safira, Dimas Raditya","director":"Satria Wisesa","synopsis":"Musisi muda pulang untuk menjual studio peninggalan ayahnya. Sebuah rekaman yang belum selesai membuatnya kembali bermain musik bersama teman-teman lama dan menghadapi percakapan yang selalu ia hindari."}'::jsonb),
('f13','film','Penumpang Terakhir','Thriller','{"id":"f13","type":"film","title":"Penumpang Terakhir","tagline":"Satu kursi kosong. Satu nama hilang.","genre":"Thriller","year":2026,"rating":"8.3","age":"16+","duration":"1j 39m","image":"https://images.unsplash.com/photo-1519501025264-65ba15a82390?auto=format&fit=crop&w=900&q=80","color":"#352b47","cast":"Reza Anggara, Sinta Ayu","director":"Raka Wibawa","synopsis":"Konduktor kereta malam menemukan tiket dengan nama penumpang yang hilang bertahun-tahun lalu. Saat kereta berhenti di stasiun tanpa petugas, setiap penumpang ternyata menyimpan versi cerita yang berbeda."}'::jsonb),
('f14','film','Rumah Tanpa Nomor','Thriller','{"id":"f14","type":"film","title":"Rumah Tanpa Nomor","tagline":"Alamatnya hilang, rahasianya tinggal.","genre":"Thriller","year":2025,"rating":"8.0","age":"16+","duration":"1j 33m","image":"https://images.unsplash.com/photo-1484154218962-a197022b5858?auto=format&fit=crop&w=900&q=80","color":"#3c4037","cast":"Fajar Mahendra, Dian Paramita","director":"Damar Seno","synopsis":"Petugas pemetaan menemukan sebuah rumah yang tidak muncul dalam dokumen kota. Penghuninya mengenali dirinya, tetapi semua foto di rumah itu memperlihatkan masa kecil yang sama sekali tidak ia ingat."}'::jsonb),
('f15','film','Jejak di Balik Kabut','Thriller','{"id":"f15","type":"film","title":"Jejak di Balik Kabut","tagline":"Semakin dekat, semakin samar.","genre":"Thriller","year":2024,"rating":"8.2","age":"16+","duration":"1j 46m","image":"https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=900&q=80","color":"#253f38","cast":"Maya Sekar, Bagas Aji","director":"Raka Wibawa","synopsis":"Relawan pencarian menemukan jejak pendaki hilang yang berakhir di menara pengawas terkunci. Kabut memutus jalur pulang, sementara pesan radio dari menara mulai menyebut nama anggota tim satu per satu."}'::jsonb),
('f16','film','Pulau di Balik Angin','Petualangan','{"id":"f16","type":"film","title":"Pulau di Balik Angin","tagline":"Peta berakhir, perjalanan dimulai.","genre":"Petualangan","year":2026,"rating":"8.4","age":"SU","duration":"1j 48m","image":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=900&q=80","color":"#24575b","cast":"Rani Puspita, Aksa Mahardika","director":"Bayu Pamungkas","synopsis":"Dua sahabat mengikuti peta buatan seorang pelaut tua menuju pulau kecil yang sulit dicapai. Mereka harus belajar membaca angin dan bekerja sama dengan warga untuk menemukan mercusuar yang lama padam."}'::jsonb),
('f17','film','Jalan Menuju Fajar','Petualangan','{"id":"f17","type":"film","title":"Jalan Menuju Fajar","tagline":"Tujuan boleh sama, alasan berbeda.","genre":"Petualangan","year":2025,"rating":"7.7","age":"SU","duration":"1j 37m","image":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=900&q=80","color":"#4b4940","cast":"Tara Kusuma, Kinan Putri","director":"Intan Maharani","synopsis":"Sekelompok pesepeda menempuh jalur pegunungan untuk mengantar buku ke sekolah terpencil. Kerusakan sepeda dan perubahan cuaca menguji rencana mereka, tetapi pertemuan di perjalanan membuka banyak jalan baru."}'::jsonb),
('f18','film','Ekspedisi Hutan Cahaya','Petualangan','{"id":"f18","type":"film","title":"Ekspedisi Hutan Cahaya","tagline":"Keajaiban tumbuh di tempat yang dijaga.","genre":"Petualangan","year":2024,"rating":"8.1","age":"SU","duration":"1j 43m","image":"https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=900&q=80","color":"#234b3f","cast":"Kevin Wijaya, Nara Putri","director":"Dewangga Putra","synopsis":"Mahasiswa biologi dan pemandu lokal mencari tumbuhan bercahaya yang hanya muncul setelah hujan pertama. Penemuan mereka mengubah ekspedisi menjadi usaha melindungi hutan dan pengetahuan masyarakat yang menjaganya."}'::jsonb),
('s4','serial','Di Ujung Peta','Petualangan','{"id":"s4","type":"serial","title":"Di Ujung Peta","tagline":"Indonesia, dari dekat.","genre":"Petualangan","year":2025,"rating":"8.4","age":"SU","duration":"1 musim · 5 episode","episodes":5,"image":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=900&q=80","color":"#24575b","cast":"Kinan Putri, Aksa Mahardika","director":"Bayu Pamungkas","synopsis":"Dua sahabat mengunjungi desa-desa terpencil dan mendokumentasikan cerita penduduknya. Sebuah perjalanan tentang alam, rumah, dan hal-hal kecil yang sering terlewat."}'::jsonb)
